<template><view class="page"><view class="bar"><text @tap="back">‹</text><text>新建空间</text><text @tap="save">保存</text></view><view class="content"><text class="label">空间名称</text><input v-model="form.name" class="input" placeholder="例如：我们的旅行"/><text class="label">空间类型</text><picker :range="typeNames" @change="chooseType"><view class="picker">{{ typeNames[typeIndex] }}</view></picker><textarea v-model="form.description" class="textarea" auto-height maxlength="500" placeholder="写一句空间介绍（可选）"/><text class="hint">创建权限由后台账号设置控制；创建后可直接发布文章和建立相册。</text><button class="primary" :loading="saving" @tap="save">创建空间</button></view></view></template>
<script>import{createSpace}from'../../services/api';export default{data(){return{form:{name:'',description:''},types:['couple','family','friends','personal'],typeNames:['双人空间','家庭空间','好友空间','个人空间'],typeIndex:0,saving:false}},methods:{chooseType(e){this.typeIndex=Number(e.detail.value)},async save(){if(this.saving)return;if(!this.form.name.trim()){uni.showToast({title:'请填写空间名称',icon:'none'});return}this.saving=true;try{const space=await createSpace({name:this.form.name.trim(),description:this.form.description.trim()||null,type:this.types[this.typeIndex]});uni.redirectTo({url:'/pages/space-detail/index?id='+space.id})}catch(e){uni.showToast({title:'创建失败，请检查空间权限',icon:'none'})}finally{this.saving=false}},back(){uni.navigateBack({delta:1})}}}</script>
<style scoped>.page{height:100vh;background:#f1eee5}.bar{height:calc(var(--status-bar-height) + 104rpx);padding:var(--status-bar-height) 28rpx 0;box-sizing:border-box;display:flex;align-items:center;justify-content:space-between;background:#fffdf8;color:#17211d;font-family:Georgia,'Songti SC',serif;font-size:27rpx;font-weight:700}.bar text:first-child{font-size:56rpx;line-height:52rpx}.bar text:last-child{color:#1d6347;font-family:inherit;font-size:22rpx}.content{padding:38rpx 28rpx}.label{display:block;margin-top:20rpx;color:#9b611f;font-size:18rpx;font-weight:800;letter-spacing:3rpx}.input,.picker,.textarea{width:100%;box-sizing:border-box;border-radius:22rpx;background:#fffdf8;color:#17211d}.input{height:88rpx;margin-top:13rpx;padding:0 22rpx;font-size:25rpx}.picker{margin-top:13rpx;padding:22rpx;color:#1d6347;font-size:22rpx}.textarea{min-height:190rpx;margin-top:13rpx;padding:22rpx;font-size:22rpx;line-height:35rpx}.hint{display:block;margin-top:21rpx;color:rgba(23,33,29,.48);font-size:19rpx;line-height:30rpx}.primary{height:86rpx;margin-top:30rpx;border-radius:22rpx;color:#fff;background:#163a2b;font-size:24rpx;font-weight:700}.primary:after{border:none}</style>
